    11   * When we go back from the chat opened in the Chats section to the chat opened in the Search RHP we have to pop the Home screen from the Bottom tab navigator to display correctly Search page under RHP on native platform.
    12   * It fixes this issue: https://github.com/Expensify/App/issues/48882
    13   */
    14  function beforeRemoveReportOpenedFromSearchRHP(event: EventArg<'beforeRemove', true>) {
    15      if (!navigationRef.current) {
    16          return;
    17      }
    18
    19      const state = navigationRef.current?.getRootState() as State<RootStackParamList>;
    20
    21      if (!state) {
    22          return;
    23      }
    24
    25      const shouldPopHome =
    26          state.routes?.length >= 3 &&
    27          state.routes.at(-1)?.name === SCREENS.REPORT &&
    28          state.routes.at(-2)?.name === NAVIGATORS.RIGHT_MODAL_NAVIGATOR &&
    29          getTopmostBottomTabRoute(state)?.name === SCREENS.HOME;
    30
    31      if (!shouldPopHome) {
    32          return;
    33      }
    34
    35      event.preventDefault();
    36      const bottomTabState = state?.routes?.at(0)?.state;
    37      navigationRef.dispatch({...StackActions.pop(), target: bottomTabState?.key});
    38      Navigation.goBack();
    39  }
